      'lede.two': 'I due cerchi sono due numeri A e B, ciascuno scritto come la sua fattorizzazione in numeri primi — tutto ciò che si trova dentro un cerchio si moltiplica per dare quel numero. A ∩ B contiene i numeri primi che appartengono a entrambe le fattorizzazioni, così che quell’intersezione si moltiplica per dare il numero più grande che divide entrambi, mentre A \\ B e B \\ A contengono i numeri primi che appartengono solo a uno dei due.',
      'lede.three': 'I tre cerchi sono tre numeri, ciascuno scritto come la sua fattorizzazione in numeri primi — tutto ciò che si trova dentro un cerchio si moltiplica per dare quel numero. Un numero primo in (A∩B) \\ C appartiene ad A e B ma non a C, così che quell’intera lente si moltiplica per dare A ∩ B; un numero primo in A∩B∩C appartiene a tutti e tre insieme, così che il centro si moltiplica per dare A ∩ B ∩ C; un numero primo in A \\ (B ∪ C) appartiene solo ad A.',
