      eyebrow: 'пересечения и разности множеств',
      'lede.two': 'Два круга — это два числа A и B, каждое записанное как своё разложение на простые множители — всё внутри круга при умножении даёт это число. A ∩ B содержит простые числа, принадлежащие обоим разложениям, поэтому это пересечение при умножении даёт наибольшее число, делящее оба, а A \\ B и B \\ A содержат простые числа, принадлежащие только одному из них.',
      'lede.three': 'Три круга — это три числа, каждое записанное как своё разложение на простые множители — всё внутри круга при умножении даёт это число. Простое число в (A∩B) \\ C принадлежит A и B, но не C, поэтому вся эта линза при умножении даёт A ∩ B; простое число в A∩B∩C принадлежит всем трём сразу, поэтому центр при умножении даёт A ∩ B ∩ C; простое число в A \\ (B ∪ C) принадлежит только A.',
