      'lede.two': 'दोनों वृत्त दो संख्याएँ A और B हैं, हर एक को उसके अभाज्य गुणनखंडन के रूप में लिखा गया है — वृत्त के अंदर की हर चीज़ का गुणनफल वही संख्या होता है। A ∩ B में वे अभाज्य संख्याएँ हैं जो दोनों गुणनखंडनों में आती हैं, इसलिए वह प्रतिच्छेदन गुणा करने पर उस सबसे बड़ी संख्या के बराबर होता है जो दोनों को विभाजित करती है, जबकि A \\ B और B \\ A में वे अभाज्य संख्याएँ हैं जो केवल एक से संबंधित हैं।',
      'lede.three': 'तीनों वृत्त तीन संख्याएँ हैं, हर एक को उसके अभाज्य गुणनखंडन के रूप में लिखा गया है — वृत्त के अंदर की हर चीज़ का गुणनफल वही संख्या होता है। (A∩B) \\ C की कोई अभाज्य संख्या A और B की है पर C की नहीं, इसलिए वह पूरा लेंस गुणा करने पर A ∩ B बनता है; A∩B∩C की कोई अभाज्य संख्या तीनों की एक साथ है, इसलिए केंद्र का गुणनफल A ∩ B ∩ C होता है; A \\ (B ∪ C) की कोई अभाज्य संख्या केवल A की है।',
