      'lede.two': '两个圆代表两个数 A 和 B，每个数都写成它的素因数分解——圆内的所有素数相乘就得到那个数。A ∩ B 包含同时属于两个分解的素数，因此这个交集相乘后得到同时整除两者的最大数，而 A \\ B 和 B \\ A 包含只属于其中一个的素数。',
      'lede.three': '三个圆代表三个数，每个数都写成它的素因数分解——圆内的所有素数相乘就得到那个数。位于 (A∩B) \\ C 中的素数属于 A 和 B 但不属于 C，所以整个透镜形区域相乘后得到 A ∩ B；位于 A∩B∩C 中的素数同时属于三个数，所以中心相乘后得到 A ∩ B ∩ C；位于 A \\ (B ∪ C) 中的素数只属于 A。',
