      'lede.two': '二つの円は二つの数AとBを表し、それぞれ素因数分解の形で書かれています。円の中のものをすべて掛けると、その数になります。A ∩ Bには両方の分解に共通する素数が入っているので、この共通部分を掛け合わせると両方を割り切る最大の数になります。一方、A \\ BとB \\ Aには、どちらか一方だけに属する素数が入っています。',
