      'lede.two': 'Kedua lingkaran itu adalah dua bilangan A dan B, masing-masing ditulis sebagai faktorisasi primanya — semua yang ada di dalam sebuah lingkaran dikalikan menjadi bilangan itu. A ∩ B memuat bilangan prima yang termasuk dalam kedua faktorisasi, sehingga irisan itu dikalikan menjadi bilangan terbesar yang membagi keduanya, sedangkan A \\ B dan B \\ A memuat bilangan prima yang hanya termasuk dalam salah satunya.',
      'lede.three': 'Ketiga lingkaran itu adalah tiga bilangan, masing-masing ditulis sebagai faktorisasi primanya — semua yang ada di dalam sebuah lingkaran dikalikan menjadi bilangan itu. Bilangan prima di (A∩B) \\ C termasuk dalam A dan B tetapi tidak dalam C, sehingga seluruh lensa itu dikalikan menjadi A ∩ B; bilangan prima di A∩B∩C termasuk dalam ketiganya sekaligus, sehingga bagian tengah dikalikan menjadi A ∩ B ∩ C; bilangan prima di A \\ (B ∪ C) hanya termasuk dalam A.',
