      'lede.two': 'ئەم دوو بازنەیە دوو ژمارە پیشان دەدەن، A و B، ھەریەکەیان وەک شیکردنەوەی سەرەتایی خۆی نووسراوە — ھەموو ئەوەی لە ناو بازنەیەکدایە ئەگەر لێک بدرێت دەبێتە ئەو ژمارەیە. \u2066A ∩ B\u2069 ئەو ژمارە سەرەتاییانە لەخۆ دەگرێت کە سەر بە ھەردوو شیکردنەوەکەن، بۆیە ئەگەر ئەم یەکتربڕینە لێک بدرێت دەبێتە گەورەترین ژمارە کە ھەردووکیان دابەش دەکات، لە کاتێکدا \u2066A \\ B\u2069 و \u2066B \\ A\u2069 ئەو ژمارە سەرەتاییانە لەخۆ دەگرن کە تەنیا سەر بە یەکێک لەوانن.',
      'lede.three': 'ئەم سێ بازنەیە سێ ژمارە پیشان دەدەن، ھەریەکەیان وەک شیکردنەوەی سەرەتایی خۆی نووسراوە — ھەموو ئەوەی لە ناو بازنەیەکدایە ئەگەر لێک بدرێت دەبێتە ئەو ژمارەیە. ژمارەیەکی سەرەتایی لە \u2066(A∩B) \\ C\u2069 دا سەر بە A و B دەبێت بەڵام سەر بە C نابێت، بۆیە ئەو پارچەیە بە تەواوی ئەگەر لێک بدرێت دەبێتە \u2066A ∩ B\u2069؛ ژمارەیەکی سەرەتایی لە \u2066A∩B∩C\u2069 دا سەر بە ھەرسێکیان دەبێت لە یەک کاتدا، بۆیە ناوەند ئەگەر لێک بدرێت دەبێتە \u2066A ∩ B ∩ C\u2069؛ ژمارەیەکی سەرەتایی لە \u2066A \\ (B ∪ C)\u2069 دا تەنیا سەر بە A دەبێت.',
