      'lede.two': 'द्वे वृत्ते द्वे सङ्ख्ये A तथा B दर्शयतः, प्रत्येका स्वस्य अभाज्यगुणनखण्डनरूपेण लिखिता — वृत्तस्य अन्तःस्थं सर्वं गुणितं तां सङ्ख्यां ददाति। A ∩ B तानि अभाज्यानि धारयति यानि उभयोः गुणनखण्डनयोः सन्ति, अतः तस्य गुणनफलम् उभयोः महत्तमसमापवर्तकः भवति; A \\ B तथा B \\ A तु तानि अभाज्यानि धारयतः यानि तयोः केवलम् एकस्य सन्ति।',
      'lede.three': 'त्रीणि वृत्तानि तिस्रः सङ्ख्याः दर्शयन्ति, प्रत्येका स्वस्य अभाज्यगुणनखण्डनरूपेण लिखिता — वृत्तस्य अन्तःस्थं सर्वं गुणितं तां सङ्ख्यां ददाति। (A∩B) \\ C इत्यस्मिन् स्थितम् अभाज्यम् A इत्यस्य B इत्यस्य च अस्ति, C इत्यस्य न, अतः तत् सम्पूर्णं मसूराकारं क्षेत्रम् A ∩ B इति गुणनफलं ददाति; A∩B∩C इत्यस्मिन् स्थितम् अभाज्यं त्रयाणां युगपत् अस्ति, अतः केन्द्रम् A ∩ B ∩ C इति गुणनफलं ददाति; A \\ (B ∪ C) इत्यस्मिन् स्थितम् अभाज्यं केवलम् A इत्यस्य अस्ति।',
